class Solution:
    def minBulbs(self, lights: List[int]) -> int:
        n = len(lights)
        bulbs = []
        for i, v in enumerate(lights):
            if v > 0:
                bulbs.append((max(0, i - v), min(n - 1, i + v)))
        bulbs.sort()
        far = [-1] * n
        j = 0
        cur = -1
        for p in range(n):
            while j < len(bulbs) and bulbs[j][0] <= p:
                cur = max(cur, bulbs[j][1])
                j += 1
            far[p] = cur
        pos, ans = 0, 0
        while pos < n:
            if far[pos] >= pos:
                pos = far[pos] + 1
            else:
                ans += 1
                pos += 3
        return ans

