import heapq
class Solution:
    def minBulbs(self, lights: List[int]) -> int:
        n = len(lights)
        ivs = sorted((max(0, i - v), min(n - 1, i + v))
                     for i, v in enumerate(lights) if v > 0)
        g, ans, i, heap = 0, 0, 0, []
        while g < n:
            while i < len(ivs) and ivs[i][0] <= g:
                heapq.heappush(heap, -ivs[i][1]); i += 1
            best = -heap[0] if heap else -1
            if best < g:
                ans += 1
                g += 3
            else:
                g = best + 1
        return ans

