class Solution {
public:
    int minBulbs(vector<int>& lights) {
        int n = lights.size();
        vector<pair<int,int>> ivs;
        for (int i = 0; i < n; ++i)
            if (lights[i] > 0)
                ivs.push_back({max(0, i - lights[i]), min(n - 1, i + lights[i])});
        sort(ivs.begin(), ivs.end());
        priority_queue<int> pq;
        int g = 0, ans = 0, i = 0;
        while (g < n) {
            while (i < (int)ivs.size() && ivs[i].first <= g)
                pq.push(ivs[i++].second);
            int best = pq.empty() ? -1 : pq.top();
            if (best < g) { ans++; g += 3; }
            else g = best + 1;
        }
        return ans;
    }
};

