class Solution {
    public int minBulbs(int[] lights) {
        int n = lights.length;
        List<int[]> ivs = new ArrayList<>();
        for (int i = 0; i < n; i++)
            if (lights[i] > 0)
                ivs.add(new int[]{Math.max(0, i - lights[i]), Math.min(n - 1, i + lights[i])});
        ivs.sort((a, b) -> a[0] - b[0]);
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        int g = 0, ans = 0, i = 0;
        while (g < n) {
            while (i < ivs.size() && ivs.get(i)[0] <= g)
                pq.offer(ivs.get(i++)[1]);
            int best = pq.isEmpty() ? -1 : pq.peek();
            if (best < g) { ans++; g += 3; }
            else g = best + 1;
        }
        return ans;
    }
}

