var minBulbs = function(lights) {
    const n = lights.length;
    const ivs = [];
    for (let i = 0; i < n; i++)
        if (lights[i] > 0)
            ivs.push([Math.max(0, i - lights[i]), Math.min(n - 1, i + lights[i])]);
    ivs.sort((a, b) => a[0] - b[0]);
    const heap = [];
    const push = v => { heap.push(v); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (heap[p] >= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
    const pop = () => { const t = heap[0], l = heap.pop();
        if (heap.length) { heap[0] = l; let i = 0;
            for (;;) { let c = 2 * i + 1; if (c >= heap.length) break;
                if (c + 1 < heap.length && heap[c + 1] > heap[c]) c++;
                if (heap[i] >= heap[c]) break;
                [heap[i], heap[c]] = [heap[c], heap[i]]; i = c; } }
        return t; };
    let g = 0, ans = 0, i = 0;
    while (g < n) {
        while (i < ivs.length && ivs[i][0] <= g) push(ivs[i++][1]);
        const best = heap.length ? heap[0] : -1;
        if (best < g) { ans++; g += 3; } else g = best + 1;
    }
    return ans;
};
